<?php
declare(strict_types=1);
require __DIR__ . '/../includes/db.php';
if (empty($_SESSION['blog_admin_id'])) { header('Location: login.php'); exit; }
if (($_SESSION['blog_admin_role'] ?? 'admin') !== 'admin') { http_response_code(403); exit('Bạn không có quyền xem bảng xếp hạng nhuận bút.'); }
function cir_h($v): string { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$month=(string)($_GET['month']??date('Y-m',strtotime('first day of last month')));
if(!preg_match('/^20\d{2}-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m',strtotime('first day of last month'));
$start=$month.'-01';$end=(new DateTimeImmutable($start))->modify('first day of next month')->format('Y-m-d');
$q=$pdo->prepare("SELECT m.id,m.display_name,m.email,COUNT(r.id) reward_count,
 COALESCE(SUM(r.amount),0) total_amount,
 COALESCE(SUM(CASE WHEN r.payment_status='paid' THEN r.amount ELSE 0 END),0) paid_amount,
 COALESCE(SUM(CASE WHEN r.payment_status='pending' THEN r.amount ELSE 0 END),0) pending_amount
 FROM members m LEFT JOIN contributor_rewards r ON r.member_id=m.id AND r.created_at>=? AND r.created_at<?
 WHERE m.account_type='contributor' GROUP BY m.id,m.display_name,m.email
 HAVING reward_count>0 ORDER BY total_amount DESC,paid_amount DESC,m.display_name ASC");
$q->execute([$start,$end]);$rows=$q->fetchAll();
$total=0.0;$paid=0.0;$pending=0.0;foreach($rows as $r){$total+=(float)$r['total_amount'];$paid+=(float)$r['paid_amount'];$pending+=(float)$r['pending_amount'];}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Xếp hạng nhuận bút CTV | Truyện Đêm CMS</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin-white.css?v=20261121-layout2"><link rel="stylesheet" href="../css/admin-cms.css?v=20261121-cms1"><style>
.cir-wrap{max-width:1120px;margin:26px auto;padding:0 16px 40px}.cir-card{background:#fff;border:1px solid #e5e9f0;border-radius:16px;padding:21px;margin:16px 0;box-shadow:0 8px 28px #17243a0a}.cir-head{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}.cir-head h1{margin:0;color:#172033}.cir-muted{color:#718096;line-height:1.6}.cir-filter{display:flex;align-items:end;gap:10px}.cir-filter label{display:grid;gap:6px;font-size:13px;font-weight:700;color:#344054}.cir-filter input{height:42px;border:1px solid #d9e0e9;border-radius:9px;padding:0 10px;font:inherit}.cir-filter button{height:42px;padding:0 16px;border:0;border-radius:9px;background:#5b4bd8;color:#fff;font-weight:700}.cir-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:18px}.cir-stat{background:#f7f8fc;border:1px solid #edf0f5;border-radius:12px;padding:15px}.cir-stat span{display:block;color:#718096;font-size:12px}.cir-stat strong{display:block;margin-top:6px;font-size:20px;color:#172033}.cir-scroll{overflow-x:auto}.cir-table{width:100%;border-collapse:collapse;min-width:760px}.cir-table th,.cir-table td{padding:12px;border-bottom:1px solid #edf0f4;text-align:left;font-size:13px}.cir-table th{color:#718096;white-space:nowrap}.cir-table small{display:block;color:#8490a2;margin-top:4px}.cir-rank{font-weight:800;color:#5b4bd8}.cir-note{padding:12px;background:#f4f6fb;border-radius:10px;color:#596579;font-size:13px;line-height:1.6}@media(max-width:650px){.cir-stats{grid-template-columns:1fr}.cir-card{padding:15px}.cir-filter{width:100%}.cir-filter label{flex:1}}
</style></head><body class="admin-theme"><?php include __DIR__.'/_nav.php';?><main class="cir-wrap"><section class="cir-card"><div class="cir-head"><div><h1>Xếp hạng thu nhập CTV</h1><p class="cir-muted">Bảng thống kê nội bộ dành riêng cho quản trị viên, xếp theo tổng nhuận bút ghi nhận trong tháng.</p></div><form method="get" class="cir-filter"><label>Chọn tháng<input type="month" name="month" value="<?=cir_h($month)?>"></label><button type="submit">Xem báo cáo</button></form></div><div class="cir-stats"><div class="cir-stat"><span>Tổng nhuận bút ghi nhận</span><strong><?=number_format($total,0,',','.')?>đ</strong></div><div class="cir-stat"><span>Đã thanh toán</span><strong><?=number_format($paid,0,',','.')?>đ</strong></div><div class="cir-stat"><span>Còn chờ thanh toán</span><strong><?=number_format($pending,0,',','.')?>đ</strong></div></div></section><section class="cir-card"><h2>Thứ hạng cộng tác viên · <?=cir_h($month)?></h2><div class="cir-scroll"><table class="cir-table"><thead><tr><th>Hạng</th><th>Cộng tác viên</th><th>Số khoản</th><th>Tổng nhuận bút</th><th>Đã trả</th><th>Đang chờ</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td class="cir-rank">#<?=$i+1?></td><td><strong><?=cir_h($r['display_name'])?></strong><small>#<?=(int)$r['id']?> · <?=cir_h($r['email'])?></small></td><td><?=(int)$r['reward_count']?></td><td><strong><?=number_format((float)$r['total_amount'],0,',','.')?>đ</strong></td><td><?=number_format((float)$r['paid_amount'],0,',','.')?>đ</td><td><?=number_format((float)$r['pending_amount'],0,',','.')?>đ</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Tháng này chưa có khoản nhuận bút nào được ghi nhận.</td></tr><?php endif;?></tbody></table></div><p class="cir-note">Đây là báo cáo nội bộ trong CMS, không xuất hiện trên trang chủ, hồ sơ tác giả hay bảng xếp hạng công khai. Số liệu tính theo ngày ghi nhận khoản nhuận bút, bao gồm cả khoản nhập thủ công trong tháng.</p></section></main></body></html>